import { IDataBackend } from './data-backend.interface';
import { MatrixService } from './matrix.service';

/**
 * MatrixBackend - Phase 2-5 Implementation
 * 
 * This class implements the IDataBackend interface using Matrix protocol
 * for user data storage, poll management, and synchronization.
 * 
 * Phase 2 Implementation includes:
 * - User authentication via Matrix
 * - User data storage in private Matrix rooms
 * - User settings and preferences management
 * 
 * Phase 3 Implementation includes:
 * - Poll room creation and management
 * - Poll metadata and option storage
 * - Voter data management within poll rooms
 * 
 * Phase 4 Implementation includes:
 * - Rating aggregation across voter rooms
 * - Delegation request/response events
 * - Real-time event handling
 * 
 * Phase 5 Implementation includes:
 * - Offline event queue for disconnected operation
 * - Poll-password encryption layer (AES-GCM)
 * - Cache warmup for performance optimization
 */
export class MatrixBackend implements IDataBackend {
  
  constructor(private matrixService: MatrixService) {}
  
  async init(): Promise<void> {
    await this.matrixService.initClient();
  }
  
  async login(email: string, password: string): Promise<void> {
    await this.matrixService.login(email, password);
  }
  
  async register(email: string, password: string): Promise<void> {
    await this.matrixService.register(email, password);
  }
  
  async logout(): Promise<void> {
    await this.matrixService.logout();
  }
  
  isLoggedIn(): boolean {
    return this.matrixService.isLoggedIn();
  }
  
  async getUserData(key: string): Promise<any> {
    return await this.matrixService.getUserData(key);
  }
  
  async setUserData(key: string, value: any): Promise<void> {
    await this.matrixService.setUserData(key, value);
  }
  
  async deleteUserData(key: string): Promise<void> {
    await this.matrixService.deleteUserData(key);
  }
  
  // ========================================================================
  // Phase 3: Poll Data Management
  // ========================================================================
  
  async createPoll(pollId: string, title: string): Promise<string> {
    // idempotent: a poll room that exists already (e.g. from an earlier,
    // partial migration run) is reused
    await this.matrixService.getOrCreatePollRoom(pollId, title);
    return pollId;
  }
  
  async getPollData(pollId: string, key: string): Promise<any> {
    // 'due' and 'state' live in their own state events (see setPollData):
    if (key === 'due' || key === 'state') {
      const value = (await this.matrixService.getAllPollData(pollId))[key];
      return value ?? null;
    }
    return await this.matrixService.getPollData(pollId, key);
  }
  
  async setPollData(pollId: string, key: string, value: any): Promise<void> {
    // The app keeps the deadline and the lifecycle state in dedicated,
    // unencrypted state events that the guard bot and other clients read
    // (see DataService.change_poll_state), so they are routed there:
    if (key === 'due') {
      await this.matrixService.setPollDeadline(pollId, value);
      return;
    }
    if (key === 'state') {
      await this.matrixService.changePollState(pollId, value);
      return;
    }
    await this.matrixService.setPollData(pollId, key, value);
  }
  
  async deletePollData(pollId: string, key: string): Promise<void> {
    await this.matrixService.deletePollData(pollId, key);
  }
  
  async getVoterData(pollId: string, voterId: string, key: string): Promise<any> {
    return await this.matrixService.getVoterData(pollId, voterId, key);
  }
  
  async setVoterData(pollId: string, voterId: string, key: string, value: any): Promise<void> {
    await this.matrixService.setVoterData(pollId, voterId, key, value);
  }
  
  async deleteVoterData(pollId: string, voterId: string, key: string): Promise<void> {
    await this.matrixService.deleteVoterData(pollId, voterId, key);
  }
  
  // ========================================================================
  // Phase 4: Voting Implementation
  // ========================================================================
  
  async submitRating(pollId: string, optionId: string, rating: number): Promise<void> {
    await this.matrixService.submitRating(pollId, optionId, rating);
  }
  
  async getRatings(pollId: string): Promise<Map<string, Map<string, number>>> {
    return await this.matrixService.getRatings(pollId);
  }
  
  async addOption(pollId: string, optionId: string, option: {name: string; description?: string; url?: string}): Promise<void> {
    // options are timeline events in the poll room, not poll data state
    // events, so that they are immutable server-side (see MatrixService)
    await this.matrixService.addOption(pollId, optionId, option);
  }
  
  async getOptions(pollId: string): Promise<Map<string, {name: string; description: string; url: string}>> {
    return await this.matrixService.getOptions(pollId);
  }
  
  async requestDelegation(pollId: string, delegateId: string, optionIds: string[]): Promise<string> {
    return await this.matrixService.requestDelegation(pollId, delegateId, optionIds);
  }
  
  async respondToDelegation(pollId: string, delegationId: string, accept: boolean, acceptedOptions?: string[]): Promise<void> {
    await this.matrixService.respondToDelegation(pollId, delegationId, accept, acceptedOptions);
  }
  
  async setupPollEventHandlers(pollId: string): Promise<void> {
    await this.matrixService.setupPollEventHandlers(pollId);
  }
  
  teardownPollEventHandlers(pollId: string): void {
    this.matrixService.teardownPollEventHandlers(pollId);
  }
  
  // ========================================================================
  // Phase 5: Advanced Features
  // ========================================================================
  
  isOnline(): boolean {
    return this.matrixService.isOnline();
  }
  
  getOfflineQueueSize(): number {
    return this.matrixService.getOfflineQueueSize();
  }
  
  async processOfflineQueue(): Promise<number> {
    return await this.matrixService.processOfflineQueue();
  }
  
  async clearOfflineQueue(): Promise<void> {
    await this.matrixService.clearOfflineQueue();
  }
  
  async encryptWithPassword(data: any, password: string, pollId: string): Promise<string> {
    return await this.matrixService.encryptWithPassword(data, password, pollId);
  }
  
  async decryptWithPassword(encryptedData: string, password: string, pollId: string): Promise<any> {
    return await this.matrixService.decryptWithPassword(encryptedData, password, pollId);
  }
  
  async warmupCache(pollId: string): Promise<void> {
    await this.matrixService.warmupCache(pollId);
  }
  
  getBackendType(): 'couchdb' | 'matrix' | 'memory' {
    return 'matrix';
  }
}
